import urllib.request
for track in ['omimAv','omimAvSnp']:
 url=f'https://api.genome.ucsc.edu/getData/track?genome=hg38;track={track};chrom=chr7;start=155811822;end=155812122'
 try:
  print(track, urllib.request.urlopen(url,timeout=20).read().decode()[:3000])
 except Exception as e: print(track,e)
PY"

